void opeu_para_clear(uint8_t ds[65536]) {
  ELEMENT_P e;
  UNIT_P    u;
  uint8_t   n;
  CLEAR_COUNT(SIDE);
  u = UNITS(SIDE);
  for (n = 0; n < 32; NEXT_UNIT(u), n++)
    if (UNIT_FLAGS(u) & 0x10)
      UNIT_FLAGS(u) = 0;
  e = ELEMENTS(SIDE);
  for (n = 0; n < 128; NEXT_ELEMENT(e), n++)
    if (ELEMENT_FLAGS(e) & 0x10)
      ELEMENT_FLAGS(e) = 0;
}

/* Without a paratroop unit the original falls off the end; AX still holds
 * the side's units-table address (FALL_OFF_READY models that on hosts). */
uint16_t opeu_para_ready(uint8_t ds[65536], ParaEvent event) {
  UNIT_P  u;
  uint8_t n;
  u = UNITS(SIDE);
  for (n = 0; n < 32; NEXT_UNIT(u), n++) {
    if (UNIT_FLAGS(u) & 0x10) {
      if (GROUP_FLAGS(u) & 4)
        return 1;
      return 0;
    }
  }
  FALL_OFF_READY(u);
}

uint16_t opeu_para_drop_due(uint8_t ds[65536], ParaEvent event) {
  PARA_P p;
  p = PARA_OF(SIDE);
  if (P_COUNT(p)) {
    SUB_DAYS(p);
    if (!READY() || !CELL_OK(P_X(p), P_Y(p)))
      CLEAR();
    else if (!SUB_WAIT(p))
      switch (REPORT(P_DAYS(p))) {
        case 0: return 1;
        case 1: P_WAIT(p) = 1; break;
        case 2: CLEAR();
      }
  }
  return 0;
}

void opeu_para_drop_present(uint8_t ds[65536], ParaEvent event) {
  if (STATUS(SIDE) == 1)
    MESSAGE_7B7E(TEMPLATE(RECORD_MASK(SIDE_RECORD(SIDE, 1)), 6));
  else
    MESSAGE_7B90(SIDE_RECORD(OPPOSITE(SIDE), 3));
  CUE();
}

/* Local names fix C 6.0a's frame slots (hx -2, unit -4, hy -6, mapx -8,
 * mapy -10, drops -12, rec -14, was -16, left -18, vy -20); declaring
 * left,hx,hy,vy in this order gives CMP [vy],AX for vy==hy. */
void opeu_para_drop_event(uint8_t ds[65536], ParaEvent event, uint16_t segment,
                          uint16_t bp) {
  SIDE_P rec;
  PARA_P drops;
  UNIT_P unit;
  DROP_LOCALS;
  uint8_t mapx, mapy, was;
  rec      = SIDE_REC(SIDE);
  drops    = PARA_IN(rec);
  mapx     = P_X(drops);
  mapy     = P_Y(drops);
  was      = MAP_MODE;
  MAP_MODE = 1;
  CENTER(mapx, mapy, FOR_STATUS(SIDE));
  left = P_COUNT(drops);
  SUB_LOST(rec, left);
  SUB_USED(rec, P_TROOPS(drops));
  opeu_sub_word(DAMAGE(mapx, mapy, opeu_min16(left, 0x59) / 30), &left);
  HX = mapx;
  HY = mapy;
  VIEW_PIXEL();
  for (vy = 0x15c; vy >= 0x54; vy--) {
    if (vy <= 0x114 && left == 0) {
      DESTROYED();
      break;
    }
    DRAW(HX, vy, SIDE);
    if (vy == HY)
      SHOW(0xfa, FOR_STATUS(SIDE));
    if (HY - vy == 0x20) {
      MUSIC7();
      unit = CREATE(SIDE, drops);
      if (LAND(unit, (P_COUNT(drops) - left) * 10))
        ARRIVAL(unit);
    }
    DELAY(1);
    RESTORE(HX, vy);
  }
  MAP_MODE = was;
  if (left) {
    RETURN_AIRCRAFT(SIDE, 3);
    ADD_RETURNED(rec, left);
  }
  CLEAR();
  ZERO_COUNT(drops);
}

